            for h in L[x][2]: g.setdefault(x,set()).add(h); g.setdefault(h,set()).add(x)
    dist={o:0};prev={};pq=[(0,o)]
    while pq:
        du,u=heapq.heappop(pq)
        if u==d: break
        if du>dist[u]: continue
        if u!=o and not L[u][1]: continue
        for v in g.get(u,()):
